#include <stdio.h>

typedef struct { int key; int idx; } Elem;

static long cmp_count = 0, swap_count = 0;

void selection_sort(Elem a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++) {
            cmp_count++;
            if (a[j].key < a[min].key) min = j;
        }
        if (min != i) {
            Elem t = a[i]; a[i] = a[min]; a[min] = t;
            swap_count++;
        }
    }
}

int is_stable(const Elem a[], int n) {
    for (int i = 0; i + 1 < n; i++) {
        if (a[i].key == a[i + 1].key && a[i].idx > a[i + 1].idx) return 0;
    }
    return 1;
}

int main(void) {
    /* 经典反例: 2a 在前、2b 在后，首轮把最小的 1 与首元素 2a 交换 -> 2a 被换到 2b 后面 */
    Elem a[] = {{2,0},{2,1},{1,2}};
    int n = (int)(sizeof(a) / sizeof(a[0]));

    printf("反例序列 (key,idx):");
    for (int i = 0; i < n; i++) printf(" (%d,%d)", a[i].key, a[i].idx);
    printf("\n");

    selection_sort(a, n);

    printf("排序结果 (key,idx):");
    for (int i = 0; i < n; i++) printf(" (%d,%d)", a[i].key, a[i].idx);
    printf("\n");
    printf("是否稳定 = %s\n", is_stable(a, n) ? "是" : "否");
    printf("原因: 首轮把 min=1 与首元素 2(idx=0) 跨距离交换，两个 2 的相对顺序被颠倒\n");

    /* 大规模：复杂度与输入无关 */
    Elem b[200];
    for (int i = 0; i < 200; i++) { b[i].key = 200 - i; b[i].idx = i; }  /* 逆序 */
    cmp_count = swap_count = 0;
    selection_sort(b, 200);
    printf("\n--- n=200 逆序 ---\n比较次数 = %ld (理论 n(n-1)/2 = %d)\n", cmp_count, 200 * 199 / 2);
    printf("交换次数 = %ld\n", swap_count);

    Elem c[200];
    for (int i = 0; i < 200; i++) { c[i].key = i; c[i].idx = i; }        /* 已有序 */
    cmp_count = swap_count = 0;
    selection_sort(c, 200);
    printf("\n--- n=200 已有序 ---\n比较次数 = %ld (与逆序完全相同 -> 与初始序列无关)\n", cmp_count);
    printf("交换次数 = %ld\n", swap_count);
    return 0;
}
